INSERT INTO products (id, name, description, price, currency, country_id, category_id, tags, is_preorder, preorder_deadline, is_active) VALUES
  (1, 'Carlyn Flower Cozy H75142010', '· The Cozy Bag features a feminine floral pattern and a lightweight feel for effortless everyday wear Designed to contour comfortably to the body for a secure and balanced fitCARLYN’s signature round stopper allows the strap to be freely adjusted to your desired shape and length Versatile 4-way styling: tote, shoulder, crossbody, or sling Detailed with a side zip pocket for organized storage, along with an additional interior zip pocket for added security', 2300.00, 'THB', 1, 1, '["Bags","Fashion"]', 1, '2026-10-15', 1),
  (2, 'Stand Oil Day Backpack / Brown', 'A versatile everyday backpack with lightweight vegan leather.', 4000.00, 'THB', 1, 1, '["Bags"]', 1, '2026-10-18', 1),
  (3, 'Carlyn Lovey heart keyring J76323010', 'With fluffy quilting heart and bowknot details Lovie Heart Keyring capturing a lovely mood. Voluminous heart shape finished with signature quilting. Soft and lightweight fabric material. Bowknot detail added to the heart. Designs that add a pop of color to the bag. Easy attachment and detachment via Carlin heart carabiner.', 1000.00, 'THB', 1, 3, '["Accessory","Bags"]', 1, '2026-10-19', 1),
  (4, 'CAP MARDI BOLD LOGO_BROWN CREAM', 'Signature floral graphic cap in relaxed fit.', 1350.00, 'THB', 1, 4, '["Clothing","Fashion"]', 1, '2026-10-21', 1),
  (5, 'HYDRO FLASK ALL AROUND TUMBLERS 20 OZ CLOUD PINK', 'A stylish reusable tumbler designed for everyday use.', 1500.00, 'THB', 2, 5, '["Lifestyle","Home"]', 1, '2026-10-20', 1),
  (6, 'GU Tiered Flared Skirt', 'A lightweight tiered flared skirt with a soft, flowing silhouette.', 700.00, 'THB', 2, 4, '["Clothing","Fashion"]', 1, '2026-10-22', 1),
  (7, 'Onitsuka Tiger MEXICO 66 SD VIN', 'Classic Onitsuka Tiger sneakers with a clean retro design, comfortable fit, and iconic Japanese style.', 6200.00, 'THB', 2, 7, '["Shoes","Fashion"]', 1, '2026-10-24', 1),
  (8, 'SHISEIDO MEN Energizing Moisturizer Extra Light Fluid', 'A lightweight emulsion which invigorates skin through the power of hydration.', 1550.00, 'THB', 2, 8, '["Beauty","Skincare"]', 1, '2026-10-27', 1),
  (9, 'Baseus Picogo Air AM71 3C Magnetic Power Bank 5000mAh 22.5W', 'Baseus Picogo Air AM71 Magnetic Power Bank 5000mAh 22.5W features a remarkably slim 0.2-inch profile with 22.5W fast charging CCC certification, and advanced cooling technology. Its built-in NFC PowerSense enables seamless device pairing and real-time monitoring via the dedicated APP.', 2400.00, 'THB', 3, 10, '["Tech"]', 1, '2026-10-17', 1),
  (10, 'Moromoro VINTAGE SHEEPSKIN JACKET', 'Vintage sheepskin jacket designed for cozy warmth and style.', 27000.00, 'THB', 3, 4, '["Clothing","Fashion"]', 1, '2026-10-25', 1),
  (11, 'DJI Flip', 'Foldable Full-Coverage Propeller Guard. Under 249 g. Subject Tracking. Capture Your Best Angle. 1/1.3-inch CMOS Sensor. 4K/60fps HDR Video. 31-Min Max Flight Time.', 10500.00, 'THB', 3, 10, '["Tech"]', 1, '2026-10-23', 1),
  (12, 'MUVA Mini Cotton Candy-MU1071 Handbag / Shoulder Bag with Crossbody Strap', 'MUVA MINI COTTON CANDY Handbag. A minimalist handbag made from high-quality polyester fibers, offering a lightweight, strong, and durable design. It features a convenient magnetic snap closure and an elegant, simple style that is perfect for everyday use or special occasions. Compact yet spacious enough for your essentials, it adds a stylish touch to any look.', 2400.00, 'THB', 3, 1, '["Bags","Fashion"]', 1, '2026-10-28', 1),
  (13, 'FEAR OF GOD ESSENTIALS', 'Minimal everyday fashion piece with a modern streetwear style.', 3900.00, 'THB', 4, 4, '["Clothing","Fashion"]', 1, '2026-10-12', 1),
  (14, 'Beats Studio Pro Wireless Headphones', 'Noise cancelling wireless headphones with spatial audio.', 4200.00, 'THB', 4, 10, '["Tech","Lifestyle"]', 1, '2026-10-26', 1),
  (15, 'Crocs classic Chocolate', 'Classic Crocs with a comfortable everyday design.', 2250.00, 'THB', 4, 7, '["Shoes"]', 1, '2026-10-29', 1),
  (16, 'kate spade NEW YORK Protective Case Mag iPhone 17 Pro Max - Autumn Tolie', 'Stylish protective case designed for iPhone 17 Pro Max.', 2000.00, 'THB', 4, 3, '["Accessory"]', 1, '2026-10-30', 1);
